<?php $user = $user ?? []; ?><section class="content narrow"><div class="page-intro"><p>Keep your details current so the right people can reach you quickly.</p></div><form method="post" class="panel form-stack"><input type="hidden" name="action" value="profile"><label>Full name<input required name="name" value="<?= h($user['name'] ?? '') ?>"></label><label>Email address<input disabled value="<?= h($user['email'] ?? '') ?>"></label><div class="form-row"><label>Blood group<select name="blood_group"><?php foreach (['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $group): ?><option <?= ($user['blood_group'] ?? '') === $group ? 'selected' : '' ?>><?= $group ?></option><?php endforeach; ?></select></label><label>Phone<input name="phone" value="<?= h($user['phone'] ?? '') ?>"></label></div><label>Location<input name="location" value="<?= h($user['location'] ?? '') ?>"></label><button class="button primary" type="submit">Save profile <span>→</span></button></form><?php if (($user['role'] ?? '') === 'donor'): ?><div class="panel availability"><div><span class="eyebrow">Donor availability</span><h3>Ready to help?</h3><p class="muted">Let recipients know when you can donate.</p></div><form method="post"><input type="hidden" name="action" value="availability"><input type="hidden" name="available" value="<?= !empty($user['available']) ? '0' : '1' ?>"><button class="toggle <?= !empty($user['available']) ? 'on' : '' ?>" type="submit"><span></span><?= !empty($user['available']) ? 'Available' : 'Unavailable' ?></button></form></div><?php endif; ?></section>